    /**
     * Alle auswaehlbaren Icon-Namen (fuer die DCA-Optionen).
     *
     * @return array<string>
     */
    public static function names(): array
    {
        return array_keys(self::ICONS);
    }

    /**
     * Bereiche mit ihren Icon-Namen (fuer das visuelle Backend-Raster).
     *
     * @return array<string, array<string>>
     */
    public static function categories(): array
    {
        return self::CATEGORIES;
    }

    /**
     * Rendert das benannte Icon als vollstaendiges SVG. Unbekannte Namen fallen
     * auf das Standard-Icon zurueck.
     */
    public static function svg(string $name): string
    {
        $inner = self::ICONS[$name] ?? self::ICONS[self::DEFAULT];

        return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'.$inner.'</svg>';
    }
}
